import"./chunk-ZW5NV4UO.js";var e={en:{title:"Classical music on Mastodon: who and what to follow",description:"Find classical musicians, composers and listeners on Mastodon, with opera, orchestral recordings and chamber music. Browse accounts and hashtags.",heading:"Classical music on Mastodon",listTitle:"Classical music",intro:["Explore classical music through performers, composers and listeners sharing recordings, scores and concert discoveries. Opera, orchestral music, chamber works and classical guitar all have a place here.","Preview the accounts and hashtags below, then choose what belongs in your timeline. Some accounts cover other subjects too, and quieter tags can still be useful starting points."],faq:[{q:"Do I need an account?",a:"You can browse this page and preview public posts without an account. To follow people or hashtags, sign in with a Mastodon account."},{q:"Does this include contemporary classical music?",a:"Yes. Compositions and arrangements sit alongside older recordings and repertoire. Preview each account to find the balance of performance, listening and discussion you enjoy."},{q:"How do I get onto this list?",a:"Share public posts about classical music and use relevant hashtags. Profiles must meet the catalogue\u2019s activity and inclusion criteria; using a tag does not guarantee inclusion."}]},de:{title:"Klassische Musik auf Mastodon: wem du folgen kannst",description:"Klassische Musik auf Mastodon: Entdecke Profile und passende Hashtags. Lies erst einmal mit, bevor du ein Konto anlegst.",heading:"Klassische Musik auf Mastodon",listTitle:"Klassische Musik",intro:["Entdecke klassische Musik auf Mastodon: Ensembles, Musizierende und Musikbegeisterte teilen Konzerte, Aufnahmen und Einblicke in ihre Arbeit.","Schau dir die Profile und Hashtags an und entscheide, was in deine Startseite passt. Einige Tags sind auch ein Ausgangspunkt f\xFCr kleinere, ruhigere Gespr\xE4che."],faq:[{q:"Brauche ich ein Konto?",a:"Diese Seite und \xF6ffentliche Beitr\xE4ge kannst du ohne Konto ansehen. Zum Folgen von Profilen oder Hashtags meldest du dich mit einem Mastodon-Konto an."},{q:"Wo fange ich am besten an?",a:"Lies zun\xE4chst bei ein paar Profilen und Tags mit. Auch andere Themen k\xF6nnen vorkommen, und nicht unter jedem Hashtag ist gleich viel los."},{q:"Wie komme ich auf diese Liste?",a:"Teile \xF6ffentliche Beitr\xE4ge zum Thema und nutze passende Hashtags. Profile m\xFCssen die Aktivit\xE4ts- und Aufnahmekriterien des Katalogs erf\xFCllen. Ein Hashtag allein garantiert keine Aufnahme."}]}};export{e as COPY};
